// Exterior-only removal: matching colours enclosed by a roof outline stay intact.
export function exteriorCutout(planes,width,height,colours){const n=width*height,p=compositePlanes(planes),removed=new Uint8Array(n),queue=[];const visit=i=>{if(i<0||i>=n||removed[i])return;const j=i*4;if(!p[j+3]||colours.has(p[j]<<16|p[j+1]<<8|p[j+2])){removed[i]=1;queue.push(i);}};for(let x=0;x<width;x++){visit(x);visit((height-1)*width+x);}for(let y=0;y<height;y++){visit(y*width);visit(y*width+width-1);}for(let h=0;h<queue.length;h++){const i=queue[h],x=i%width;if(x)visit(i-1);if(x<width-1)visit(i+1);visit(i-width);visit(i+width);}return planes.map(p=>{const out=p.slice();for(let i=0;i<n;i++)if(removed[i])out.fill(0,i*4,i*4+4);return out;});}
export function compositePlanes(planes){const p=new Uint8ClampedArray(planes[0].length);for(const l of planes)for(let i=0;i<l.length;i+=4)if(l[i+3])p.set(l.subarray(i,i+4),i);return p;}
export function cropNativePlanes(reader,o){const m=reader.byKey(o.key),a=reader.atlas(m),b=reader.blocks(m),width=o.w*16,height=o.h*16;return{width,height,planes:a.layers.map(p=>{const out=new Uint8ClampedArray(width*height*4);for(let y=0;y<o.h;y++)for(let x=0;x<o.w;x++){const id=b[(o.rows?.[y]??o.y+y)*m.layout.width+o.x+x]&1023;for(let py=0;py<16;py++)out.set(p.subarray(((Math.floor(id/16)*16+py)*a.width+id%16*16)*4,((Math.floor(id/16)*16+py)*a.width+id%16*16+16)*4),((y*16+py)*width+x*16)*4);}return out;})};}
export function floorColours(reader,profile,o){const out=new Set();for(const[key,x,y]of[[profile.key,...profile.ground],[profile.key,...profile.path],...(o.backgroundSamples||[])]){const m=reader.byKey(key),a=reader.atlas(m),id=reader.blocks(m)[y*m.layout.width+x]&1023;for(let py=0;py<16;py++)for(let px=0;px<16;px++){let rgb;for(const p of a.layers){const i=((Math.floor(id/16)*16+py)*a.width+id%16*16+px)*4;if(p[i+3])rgb=p[i]<<16|p[i+1]<<8|p[i+2];}if(rgb!==undefined)out.add(rgb);}}if(o.backgroundRects?.length){const raw=cropNativePlanes(reader,o),p=compositePlanes(raw.planes);for(const[x,y,w,h]of o.backgroundRects)for(let dy=0;dy<h;dy++)for(let dx=0;dx<w;dx++){const i=((y+dy)*raw.width+x+dx)*4;if(p[i+3])out.add(p[i]<<16|p[i+1]<<8|p[i+2]);}}return out;}
